resource "aws_instance" "web" {
  ami           = "ami-0c55b159cbfafe1f0"
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.public.id
  vpc_security_group_ids = [aws_security_group.web_sg.id]
}

resource "aws_internet_gateway" "gw" {
  vpc_id = aws_vpc.main.id
}

resource "aws_route" "internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.gw.id
}

resource "aws_db_instance" "default" {
  engine         = "postgres"
  instance_class = "db.t4g.micro"
  db_subnet_group_name = aws_db_subnet_group.private.name
  publicly_accessible  = false
}

resource "aws_eip" "nat" {
  domain = "vpc"
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id
}

resource "aws_lb" "main" {
  name               = "web-alb"
  internal           = false
  load_balancer_type = "application"
  subnets            = [aws_subnet.pub_a.id, aws_subnet.pub_b.id]
}

resource "aws_autoscaling_group" "app_asg" {
  min_size         = 2
  max_size         = 6
  desired_capacity = 2
  target_group_arns = [aws_lb_target_group.tg.arn]
}

resource "aws_lb_listener_rule" "static" {
  listener_arn = aws_lb_listener.front_end.arn
  action {
    type = "forward"
    target_group_arn = aws_lb_target_group.static.arn
  }
  condition {
    path_pattern {
      values = ["/static/*"]
    }
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  certificate_arn   = aws_acm_certificate.cert.arn
}

resource "aws_s3_bucket_public_access_block" "block" {
  bucket = aws_s3_bucket.data.id
  block_public_acls   = true
  block_public_policy = true
}

resource "aws_db_instance" "prod_db" {
  engine         = "postgres"
  multi_az       = true
  instance_class = "db.m6i.large"
}

resource "aws_db_instance" "replica" {
  replicate_source_db = aws_db_instance.primary.identifier
  instance_class      = "db.r6g.large"
}

resource "aws_elasticache_cluster" "redis" {
  cluster_id           = "app-cache"
  engine               = "redis"
  node_type            = "cache.t4g.micro"
  num_cache_nodes      = 1
}

resource "aws_s3_bucket_lifecycle_configuration" "rule" {
  bucket = aws_s3_bucket.logs.id
  rule {
    id     = "archive-glacier"
    status = "Enabled"
    transition {
      days          = 90
      storage_class = "GLACIER"
    }
  }
}

resource "aws_iam_role_policy_attachment" "s3_read" {
  role       = aws_iam_role.app_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
}

resource "aws_kms_key" "app_key" {
  description             = "Customer Managed Key for RDS & S3"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_wafv2_web_acl_association" "alb_assoc" {
  resource_arn = aws_lb.main.arn
  web_acl_arn  = aws_wafv2_web_acl.main.arn
}

resource "aws_cloudtrail" "trail" {
  name                          = "all-events-trail"
  s3_bucket_name                = aws_s3_bucket.trail_logs.id
  include_global_service_events = true
  is_multi_region_trail         = true
}

resource "aws_lambda_function" "api" {
  function_name = "ProcessOrder"
  runtime       = "nodejs20.x"
  handler       = "index.handler"
  role          = aws_iam_role.lambda_exec.arn
}

resource "aws_sqs_queue" "orders_queue" {
  name                      = "orders.fifo"
  fifo_queue                = true
  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq.arn
    maxReceiveCount     = 3
  })
}

resource "aws_sns_topic" "order_events" {
  name = "order-placed-topic"
}

resource "aws_sns_topic_subscription" "email_sub" {
  topic_arn = aws_sns_topic.order_events.arn
  protocol  = "lambda"
  endpoint  = aws_lambda_function.email_worker.arn
}

resource "aws_dynamodb_table" "users" {
  name         = "Users"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "UserId"
  attribute {
    name = "UserId"
    type = "S"
  }
}

resource "aws_s3_bucket_notification" "upload_notify" {
  bucket = aws_s3_bucket.user_uploads.id
  lambda_function {
    lambda_function_arn = aws_lambda_function.resizer.arn
    events              = ["s3:ObjectCreated:*"]
  }
}

resource "aws_route53_record" "apex" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "cloudcraft.io"
  type    = "A"
  alias {
    name                   = aws_cloudfront_distribution.cdn.domain_name
    zone_id                = aws_cloudfront_distribution.cdn.hosted_zone_id
    evaluate_target_health = false
  }
}

resource "aws_cloudfront_distribution" "s3_distribution" {
  origin {
    domain_name = aws_s3_bucket.assets.bucket_regional_domain_name
    origin_id   = "S3-Assets"
  }
  enabled             = true
  default_root_object = "index.html"
}

resource "aws_cloudfront_origin_access_control" "oac" {
  name                              = "s3-oac"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

resource "aws_route53_record" "us" {
  zone_id        = aws_route53_zone.main.zone_id
  name           = "app.cloudcraft.io"
  type           = "A"
  set_identifier = "us-cluster"
  latency_routing_policy {
    region = "us-east-1"
  }
}

resource "aws_route53_record" "primary" {
  zone_id         = aws_route53_zone.main.zone_id
  name            = "app.cloudcraft.io"
  type            = "A"
  failover_routing_policy {
    type = "PRIMARY"
  }
}

resource "aws_codepipeline" "pipeline" {
  name     = "app-pipeline"
  role_arn = aws_iam_role.pipeline.arn
  artifact_store {
    location = aws_s3_bucket.artifacts.bucket
    type     = "S3"
  }
}

resource "aws_codedeploy_deployment_group" "bg" {
  app_name              = "web-app"
  deployment_group_name = "bluegreen-group"
  deployment_style {
    deployment_option = "WITH_TRAFFIC_CONTROL"
    deployment_type   = "BLUE_GREEN"
  }
}

terraform {
  backend "s3" {
    bucket         = "tf-state-prod"
    key            = "global/s3/terraform.tfstate"
    region         = "us-east-1"
    dynamodb_table = "terraform-locks"
    encrypt        = true
  }
}

resource "aws_launch_template" "golden" {
  name_prefix   = "golden-ami-template"
  image_id      = "ami-0123456789golden"
  instance_type = "c6g.xlarge"
}

resource "aws_eks_cluster" "prod" {
  name     = "cloudcraft-eks"
  role_arn = aws_iam_role.eks_master.arn
  vpc_config {
    subnet_ids = [aws_subnet.pri_a.id, aws_subnet.pri_b.id]
  }
}

resource "aws_eks_fargate_profile" "app" {
  cluster_name           = aws_eks_cluster.prod.name
  fargate_profile_name   = "microservices"
  pod_execution_role_arn = aws_iam_role.fargate_pod.arn
  subnet_ids             = [aws_subnet.pri_a.id]
}

resource "aws_ecr_repository" "repo" {
  name                 = "cloudcraft/core-api"
  image_tag_mutability = "IMMUTABLE"
  image_scanning_configuration {
    scan_on_push = true
  }
}

resource "aws_appmesh_mesh" "prod" {
  name = "production-mesh"
  spec {
    egress_filter {
      type = "DROP_ALL"
    }
  }
}

resource "aws_cloudwatch_composite_alarm" "p1_incident" {
  alarm_name        = "P1-Customer-Impact"
  alarm_rule        = "ALARM(HighCPU) AND ALARM(HighErrorRate)"
  alarm_actions     = [aws_sns_topic.pagerduty.arn]
}

resource "aws_flow_log" "vpc_traffic" {
  log_destination      = aws_s3_bucket.flow_logs.arn
  log_destination_type = "s3"
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.main.id
}

resource "aws_spot_instance_request" "worker" {
  ami           = "ami-arm64-al2023"
  instance_type = "c7g.large"
  spot_type     = "one-time"
}

resource "aws_s3_bucket_intelligent_tiering_configuration" "tiering" {
  bucket = aws_s3_bucket.data_lake.id
  name   = "EntireBucket"
  tiering {
    access_tier = "ARCHIVE_ACCESS"
    days        = 90
  }
}

resource "aws_ec2_transit_gateway" "hub" {
  description = "Central Enterprise Transit Hub"
  amazon_side_asn = 64512
}

resource "aws_dx_connection" "datacenter" {
  name      = "10G-Direct-Connect"
  bandwidth = "10Gbps"
  location  = "EqDC2"
}

resource "aws_dynamodb_table" "global_users" {
  name         = "GlobalUsers"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "ID"
  replica {
    region_name = "eu-central-1"
  }
}

resource "aws_fis_experiment_template" "kill_instances" {
  description = "Randomly kill 50% of EC2 nodes"
  role_arn    = aws_iam_role.fis.arn
  stop_conditions {
    source = "aws:cloudwatch:alarm"
    value  = aws_cloudwatch_metric_alarm.emergency_stop.arn
  }
}
